import {sceneMarkup,journeyMarkup,roadmapMarkup,nearbyMarkup} from './ui-story.js';
import {createSaveManager} from './storage.js';
import * as E from './engine.js';
import {drawMap,drawBattle,portrait} from './art.js';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const saves=createSaveManager({getStorage:()=>window.localStorage,migrate:E.migrateSave,fresh:E.newGame});
let state=saves.load(),tab='world',target='enemy0',timer=null,sound=false,audio=null,toastTimer,storageOk=saves.problem===null;
const loadProblem=saves.problem;
function save(){const result=saves.write(state);storageOk=result==='saved';$('save-state').textContent=result==='saved'?'Adventure saved':result==='recovery'?'Autosave paused · recover old save in Camp':'Save unavailable · use Camp backup';}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
function chime(type='click'){if(!sound)return;try{audio||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=type==='win'?660:type==='hit'?180:440;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.2);}catch{}}
const pct=(a,b)=>Math.max(0,Math.min(100,100*a/b));
function renderParty(){const b=state.battle;renderPartyStrip();$('party').innerHTML=state.party.map(h=>`<article class="hero-card ${b?.actor===h.id?'current':''} ${h.hp<=0?'fallen':''}"><div class="hero-top"><canvas class="portrait" data-portrait="${h.id}" aria-hidden="true"></canvas><div><h3>${esc(h.name)}</h3><small>${esc(h.role)}</small></div></div><div class="stat-row"><span>${h.hp<=0?'FALLEN':'HEALTH'}${h.poison?' · POISON':''}${h.shield?' · SHIELD '+h.shield:''}</span><b>${h.hp} / ${h.maxHp}</b></div><div class="track" role="meter" aria-label="${esc(h.name)} health" aria-valuenow="${h.hp}" aria-valuemin="0" aria-valuemax="${h.maxHp}"><i style="width:${pct(h.hp,h.maxHp)}%"></i></div><div class="stat-row"><span>FOCUS</span><b>${h.focus} / ${h.maxFocus}</b></div><div class="track focus"><i style="width:${pct(h.focus,h.maxFocus)}%"></i></div></article>`).join('')+(state.party.length<3?`<div class="empty-slot">${3-state.party.length} empty place${state.party.length===1?'s':''} by the fire.<br>Find companions along the road.</div>`:'');document.querySelectorAll('[data-portrait]').forEach(c=>portrait(c,c.dataset.portrait));$('level').textContent=String(state.level).padStart(2,'0');$('xp-bar').style.width=pct(state.xp,state.level*100)+'%';$('xp').textContent=`${state.xp} / ${state.level*100} XP to next level`;$('gold').textContent=state.gold;}
function renderMap(){
 $('map-nodes').innerHTML=E.NODES.map(n=>{const roam=state.world.roamers.find(r=>r.id===n.id),clear=state.cleared.includes(n.id);if(roam&&clear)return '';const x=roam?(roam.x+.5)/E.WIDTH*100:n.x,y=roam?(roam.y+.5)/E.HEIGHT*100:n.y;return '<button class="map-node '+(n.id===state.location&&E.atLandmark(state)?'current':'')+' '+(!E.unlocked(state,n)?'locked':'')+' '+(clear?'cleared':'')+' '+(x>80?'edge-right':'')+'" data-node="'+n.id+'" style="left:'+x+'%;top:'+y+'%" aria-label="Walk toward '+esc(n.name)+'" title="'+esc(n.name)+'"><span class="node-symbol">'+(clear?'✓':n.roaming?'⚠':n.type==='town'?'⌂':n.type==='boss'?'♜':n.type==='story'?'✧':'◆')+'</span><span class="node-name">'+esc(n.name)+'</span></button>';}).join('');drawMap($('scene'),state);
}
let walkingTimer=null,walkingPath=[];
function stopWalking(){clearTimeout(walkingTimer);walkingTimer=null;walkingPath=[];}
function step(dx,dy){if(state.battle||$('modal').open)return false;if(E.pendingScene(state)){stopWalking();tab='world';render();focusStory();toast('Finish this conversation before taking the road.');return false;}const previous=state.location;if(!E.walk(state,dx,dy)){stopWalking();toast(E.objective(state));return false;}tab='world';save();render();if(state.battle||E.pendingScene(state)||state.location!==previous){stopWalking();if(state.battle)target='enemy0';}return true;}
function navigate(id){stopWalking();if(!state.started){toast('Light the lantern below to begin.');return;}if(state.battle)return;if(E.pendingScene(state)){tab='world';render();focusStory();return;}const n=E.nodeById(id),roam=state.world.roamers.find(r=>r.id===id),p=roam?[roam.x,roam.y]:E.PLACES[id];if(!n||!E.unlocked(state,n)){toast(E.objective(state));return;}const path=E.pathTo(state,...p,E.NODES);if(!path){toast(E.nodeById(id)?.region==='The Salt Isles'?'Take the ferry at Witchlight Hut to reach the isles.':E.objective(state));return;}walkingPath=path;const advance=()=>{const next=walkingPath.shift();if(!next)return;const ok=step(next[0]-state.world.x,next[1]-state.world.y);if(ok&&walkingPath.length&&!state.battle)walkingTimer=setTimeout(advance,110);};advance();}
function renderBattle(){const b=state.battle;$('stage').classList.add('battle-mode');$('battle-overlay').hidden=false;drawBattle($('scene'),state);const actor=E.entity(state,b.actor);$('battle-overlay').innerHTML=`<div class="battle-top"><b>ROUND ${b.round}</b><div class="turn-queue">${[b.actor,...b.queue].filter(Boolean).slice(0,6).map(id=>`<span>${esc(E.entity(state,id)?.name)}</span>`).join('')}</div></div><div class="enemy-targets">${b.enemies.map(e=>`<button data-target="${e.id}" class="enemy-card ${target===e.id?'selected':''} ${e.hp<=0?'dead':''}" ${e.hp<=0?'disabled':''} aria-pressed="${target===e.id}"><strong>${esc(e.name)}${e.mark?' ✦':''}</strong><div class="stat-row"><span>${e.mark?'MARKED':'HEALTH'}</span><b>${e.hp}/${e.maxHp}</b></div><div class="track"><i style="width:${pct(e.hp,e.maxHp)}%"></i></div><small>${e.hp<=0?'Defeated':esc(E.intent(state,e))}</small></button>`).join('')}</div>`;
 if(b.result){$('panel').innerHTML=`<div><span class="eyebrow">${b.result==='victory'?'THE LIGHT HOLDS':b.result==='defeat'?'A FLAME CAN BE RELIT':'A ROAD STILL OPEN'}</span><h2 class="victory">${b.result==='victory'?'Victory.':b.result==='defeat'?'The company falls.':'You slip into the dark.'}</h2><p>${b.result==='victory'?'The living and fallen recover. Focus carries into your next battle. Claim your rewards and continue.':b.result==='defeat'?'Elin will bring everyone safely to Last Hearth. Recovery costs up to 15 crowns. You keep all quest progress.':'Return to your previous landmark. This encounter will wait for you.'}</p></div><div class="actions"><button class="primary" data-do="finish">${b.result==='victory'?'Claim rewards & continue':'Continue the journey'}</button></div>${battleLog()}`;return;}
 const h=actor,player=state.party.includes(h);$('panel').innerHTML=`<div class="turn-header"><h2>${player?esc(h.name)+', your move.':esc(h.name)+' is acting…'}</h2><span class="badge">${player?'YOUR TURN':'ENEMY TURN'}</span></div>${player?`<p>${esc(h.description)} Select an enemy above. Healing draughts target the most wounded ally.</p><div class="battle-actions"><button data-action="attack"><strong>Attack</strong><small>Free · ${h.atk} base damage</small></button><button data-action="skill" ${h.focus<h.cost?'disabled':''}><strong>${esc(h.skill)}</strong><small>${h.cost} focus · unique ability</small></button><button data-action="guard"><strong>Guard</strong><small>½ damage · +3 focus</small></button><button data-action="restore"><strong>Restore</strong><small>Recover 25% of your HP</small></button><button data-action="potion" ${!state.potions?'disabled':''}><strong>Draught (${state.potions})</strong><small>Heal or revive · 45 HP</small></button><button data-action="flee" ${E.nodeById(b.node).type==='boss'?'disabled':''}><strong>Flee</strong><small>75% chance · ends turn on failure</small></button></div>`:'<p>The adventure pauses whenever it is your turn.</p>'}${battleLog()}`;
 if(!player&&!timer&&!$('modal').open&&!document.hidden)timer=setTimeout(()=>{timer=null;if(state.battle&&!state.battle.result&&!$('modal').open&&!document.hidden){E.enemyAct(state);chime('hit');save();render();}},700);
}
function battleLog(){return `<div class="battle-log" role="log" aria-label="Battle events">${state.battle.log.slice(0,8).map(t=>`<div>${esc(t)}</div>`).join('')}</div>`;}
function walkingControls(){return '<div class="walk-controls" aria-label="Walk one tile"><button data-walk="0,-1" aria-label="Walk north">↑</button><button data-walk="-1,0" aria-label="Walk west">←</button><button data-walk="0,1" aria-label="Walk south">↓</button><button data-walk="1,0" aria-label="Walk east">→</button><span>Arrow keys / WASD · click a landmark to walk · Esc stops</span></div>';}
function routeButtons(){const n=E.nodeById(state.location);return `<div class="eyebrow" style="margin:6px 0 0">ROADS FROM HERE</div><div class="actions">${n.links.map(id=>{const t=E.nodeById(id),open=E.unlocked(state,t);return `<button class="route-button" data-node="${id}" ${!open?'disabled':''}>${t.type==='town'?'⌂':'↗'} ${esc(t.name)} <small>${!open?'SEALED':state.cleared.includes(id)?'CLEARED':t.type.toUpperCase()}</small></button>`;}).join('')}</div>`;}
function worldPanel(){const n=E.nodeById(state.location),scene=E.pendingScene(state);if(scene)return sceneMarkup(scene);if(state.started&&!E.atLandmark(state))return '<h2>On the road</h2><p role="status">Tile '+state.world.x+', '+state.world.y+'. Arrow keys, WASD or the direction buttons move one tile. Click a landmark to walk toward it; movement stops at an encounter or landmark.</p>'+walkingControls()+nearbyMarkup(state);if(!state.started)return `<div class="intro"><div class="eyebrow">PROLOGUE / THE LANTERN KEEPER</div><h2>Ninety nights without a sunrise.</h2><p>Your mother vanished with the dawn. Now her lantern has found its way home, and something inside it is beating like a heart.</p><p>Take the road. Find your companions. Discover what the light was keeping out.</p><button class="primary" data-do="begin">Light the lantern & begin ↗</button></div>`;
 const events={well:`<p>Give the well a memory, or take the medicine left on its stones?</p><div class="actions"><button class="choice" data-choice="memory"><strong>Give a memory</strong><span>+2 maximum focus to the current company.</span></button><button class="choice" data-choice="leave"><strong>Keep what is yours</strong><span>Take two healing draughts.</span></button></div>`,ferryman:`<p>You have time to save the man or the vial. The other will be lost.</p><div class="actions"><button class="choice" data-choice="rescue"><strong>Lift the beam</strong><span>Save the ferryman. Gain 30 crowns and his promise.</span></button><button class="choice" data-choice="vial"><strong>Catch the sunlight</strong><span>+3 attack to the company. The ferryman will be lost.</span></button></div>`,mother:`<p>“I sealed the sun to stop it from burning the world. I could hold it, Vera. I could never change it. Perhaps you can.”</p><button class="primary" data-choice="listen">Take her hand · restore health & focus</button>`};
 const after={bell:'The bell falls silent. A brass seal glows in your lantern. Beyond the river, Mothfen’s lamps answer.',mill:'You break the millwheel. The dreams return to their sleepers. A second seal settles in your lantern.',spire:'The Oracle removes his cloak. “Your mother never wanted a world without dawn. She wanted one that could survive it.” The last seal is yours.'};
 return `<div class="location-row"><div><h2>${esc(n.name)}</h2><p>${esc(n.id==='saltwick'&&state.flags.vial?'A Saltwick crew takes over the empty ferry. Their fare keeps its tidal lanterns burning. The village has survived without sunrise for generations.':n.text)}</p></div><span class="badge">${state.cleared.includes(n.id)?'CLEARED':n.region.toUpperCase()}</span></div>${n.event&&!state.flags[n.event]?events[n.event]:''}${state.cleared.includes(n.id)&&after[n.id]?`<p class="intro">${after[n.id]}</p>`:''}${n.type==='town'?`<div class="actions"><button class="primary" data-do="rest">Rest at the lantern · free</button><button data-do="shop">Visit the outfitter</button>${n.recruit?`<span class="subtle">${esc(E.HEROES[n.recruit].name)} travels with you.</span>`:''}</div>`:''}${n.optional&&state.cleared.includes(n.id)?'<p class="subtle">The blessing here has been claimed. You may train against its echo for more crowns and XP.</p><button data-do="train">Challenge the echo</button>':''}${state.flags.sun&&!state.ending&&n.id==='sun'?endingChoices():''}${state.ending&&n.id==='sun'?endingText():''}${['hut','saltwick'].includes(n.id)&&state.flags.ferryman?'<button class="primary" data-do="sail">Take the ferry · '+(state.flags.mercy?'free passage':'40 crowns')+'</button>':''}${walkingControls()}${routeButtons()}`;
}
function endingChoices(){return `<div class="ending"><h2>What should dawn become?</h2><p>The old sun yields. Your lantern can carry its fire, or scatter it into every living thing.</p><div class="actions"><button class="choice" data-ending="keeper"><strong>Become the keeper</strong><span>Guide a gentler sun. Vera’s journey ends in the sky.</span></button><button class="choice" data-ending="scatter"><strong>Give the light away</strong><span>Make a thousand small dawns. Let the kingdom learn to shine.</span></button></div></div>`;}
function endingText(){return `<div class="ending"><div class="eyebrow">CHRONICLE COMPLETE</div><h2>${state.ending==='keeper'?'The Keeper of Morning':'A Thousand Small Dawns'}</h2><p>${state.ending==='keeper'?'Vera lifts the lantern into the empty sky. Each morning, her friends leave a cup of tea on the windowsill. Each morning, its steam catches a little gold.':'The lantern opens like a flower. Every hearth, every firefly, every outstretched hand receives a spark. The first morning has no sun. It has everyone.'}</p><p>${state.flags.mercy?'The ferryman carries the lost safely home. He tells every passenger that the light once stopped to help him.':state.flags.vial?'At the river, an empty boat turns in the current. The company remembers the price of its strength.':'At the river, someone still waits for a helping hand.'} ${state.cleared.includes('archive')?'The old records are brought out of the water. This time, the kingdom keeps the truth.':''}</p><p class="subtle">${state.battles} victories · ${state.visited.length}/${E.NODES.length} places found · Company level ${state.level}. You can keep exploring or start again from Camp.</p></div>`;}
function journalPanel(){return `<div><h2>The thread of dawn</h2><p>${esc(E.objective(state))}</p></div><div class="journal-entry"><span class="subtle">THE STORY SO FAR</span><p>${state.flags.mother?'Your mother held the old sun beneath the mountain to protect the kingdom. You must overcome it and decide how to return the light.':state.flags.star?'The three seals are gathered. The keeper behind the Dawnless Gate knows the truth.':state.flags.mill?'Two guardians have fallen. The Hollow Spire keeps the last seal.':state.flags.bell?'The first seal opened the road into Mothfen. Your lantern is growing warmer.':'Elin gave you your mother’s lantern. The Thirteenth Bell holds the first seal.'}</p></div><h3>The road ahead</h3>${roadmapMarkup(state)}<h3>Places & unfinished paths</h3>${E.NODES.filter(n=>n.optional||n.event).map(n=>`<div class="journal-entry"><span class="subtle">${state.cleared.includes(n.id)||state.flags[n.event]?'COMPLETE':state.visited.includes(n.id)?'DISCOVERED':'UNEXPLORED'} · ${esc(n.name)}</span><p>${n.optional?'An optional encounter with a permanent company blessing.':'A person, a secret, or a choice along the way.'}</p></div>`).join('')}<h3>Chronicle</h3>${state.history.length?state.history.map(t=>`<div class="journal-entry"><p>${esc(t)}</p></div>`).join(''):'<p>The first page is still unwritten.</p>'}`;}
function packPanel(){return `<div><h2>The travelling satchel</h2><p>Supplies follow the company. Equipment bonuses are permanent and shown below.</p></div><div class="split"><div class="item"><h3>Healing draught <span class="coin">×${state.potions}</span></h3><p>Restore 45 HP to the most wounded hero. Revives a fallen hero in battle.</p><button data-do="potion" ${!state.potions?'disabled':''}>Use draught</button></div><div class="item"><h3>Focus tonic <span class="coin">×${state.tonics}</span></h3><p>Restore 6 focus to every hero outside battle.</p><button data-do="tonic" ${!state.tonics?'disabled':''}>Share a tonic</button></div></div><h3>Company equipment</h3>${state.party.map(h=>`<div class="item"><strong>${esc(h.name)} · ${esc(h.role)}</strong><p>Attack ${h.atk} · Initiative ${h.spd} · Maximum HP ${h.maxHp} · Maximum focus ${h.maxFocus}</p><p>${esc(h.skill)} (${h.cost} focus): ${esc(h.description)}</p><small>${['atk','hp','spd'].filter(k=>E.upgradeLevel(state,h.id,k)).map(k=>E.UPGRADES[k].name+' '+E.upgradeLevel(state,h.id,k)+'/'+E.MAX_UPGRADE).join(' · ')||'Starting equipment. Visit an outfitter in any town.'}</small></div>`).join('')}`;}
function campPanel(){const town=E.atLandmark(state)&&E.nodeById(state.location).type==='town';return `<div><h2>A moment by the fire</h2><p>Health returns after a victory. Focus persists between battles; a town rest restores everyone for free.</p></div><div class="actions"><button data-do="rest" class="primary" ${!town?'disabled':''}>Rest & recover ${town?'':'· town required'}</button><button data-do="export">Download save backup</button><button data-do="import">Load save backup</button><button data-do="reset" class="danger">Start a new chronicle</button>${hasRecovery()?'<button data-do="export-recovery">Download unreadable old save</button>':''}</div><p class="subtle">${storageOk?'Autosave is active in this browser.':loadProblem==='invalid'&&!saves.recoveryDurable?'Autosave is paused to protect your unreadable previous save. Download both your old file and a backup of this adventure before leaving.':'Browser storage is unavailable. Download a backup before leaving.'} Saves are local to your browser and device. Importing a backup replaces this adventure.</p><div class="split"><div><h3>Field guide</h3><p>Gold borders mark your location. Use arrow keys or WASD to walk across the map. Water and mountains block movement. Grey landmarks may require a seal. Explore optional paths for permanent blessings before taking on guardians.</p></div><div><h3>Battle rhythm</h3><p>Initiative + a random roll sets each round’s order. Gain 1 focus at the start of a hero’s turn. Guard gains another 3 and halves damage until their next turn. Every third round, enemies with special abilities use them; their card warns you a round ahead. Enemies target Rook more and guarding heroes less.</p></div></div>`;}
function render(){renderParty();const n=E.nodeById(state.location),b=state.battle,seals=['bell','mill','star'].filter(k=>state.flags[k]).length;$('chapter').textContent=`CHAPTER ${!state.flags.bell?'I':!state.flags.mill?'II':!state.flags.star?'III':'IV'} / ${n.region.toUpperCase()}`;$('progress').textContent=`${seals} / 3 SEALS`;$('location-title').textContent=b?n.name:n.region;$('location-subtitle').textContent=b?'Keep the light. Read the enemy. Choose your moment.':state.ending?'The world has changed. The roads remain.':'A kingdom holding its breath.';$('scene-mode').innerHTML=`<i></i> ${b?'BATTLE':E.pendingScene(state)?'STORY':'OVERWORLD'}`;$('travel-count').textContent=`DAYLESS / ${String(state.steps).padStart(3,'0')}`;$('objective').textContent=E.objective(state);$('places').textContent=state.visited.length;$('wins').textContent=state.battles;$('seals').innerHTML=[['bell','The brass seal','Bellwatch'],['mill','The river seal','Moonless Mill'],['star','The star seal','The Hollow Spire']].map(([id,title,place])=>`<div class="seal-item ${state.flags[id]?'done':''}"><span>${state.flags[id]?'✦':'◇'}</span><div><b>${title}</b><small>${state.flags[id]?'RECOVERED':place}</small></div></div>`).join('');$('field-notes').innerHTML=`<p>“${state.flags.mother?'Holding back the fire was easier than asking for help.':state.flags.mill?'The dreams were never his to grind.':state.flags.bell?'There are kind things in the dark, too.':'A lantern does not end the night. It gives you a place to begin.'}”</p><span class="subtle">${state.flags.mother?'— YOUR MOTHER':'— ELIN, KEEPER OF LAST HEARTH'}</span>`;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');b.disabled=!!state.battle;});if(b){if(!b.enemies.some(e=>e.id===target&&e.hp>0))target=b.enemies.find(e=>e.hp>0)?.id||'enemy0';renderBattle();}else{$('stage').classList.remove('battle-mode');$('battle-overlay').hidden=true;renderMap();$('panel').innerHTML=journeyMarkup(state)+({world:worldPanel,journal:journalPanel,pack:packPanel,camp:campPanel})[tab]();}}
function hasRecovery(){return !!saves.recovery();}
function download(text,name){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function weakest(){return [...state.party].sort((a,b)=>(a.hp/a.maxHp)-(b.hp/b.maxHp))[0];}
function dialog(html){stopWalking();clearTimeout(timer);timer=null;$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function help(){dialog(`<div class="eyebrow">THE TRAVELLER’S COMPANION</div><h2>Carry a little light.</h2><p>Emberwake is an original, turn-based RPG. Nothing moves while you consider your turn. Begin at Last Hearth and walk the roads to landmarks.</p><h3>On the road</h3><ul><li>Find Rook on Ashen Road and Fenn in Mothfen. The full company has three heroes.</li><li>Win the three seals at Bellwatch, Moonless Mill, and the Hollow Spire to reach the Sunken Sun.</li><li>Optional ruins reward permanent stat blessings. Towns offer free rest and two tiers of each upgrade per hero.</li><li>Defeat returns you to Last Hearth, costing up to 15 crowns. Quest progress is retained.</li></ul><h3>In battle</h3><ul><li>Select an enemy card, then choose an action. Sunshard marks a target for 50% more damage on the next hit.</li><li>Rook shields everyone, and enemies attack him more often. Guarding heroes are attacked less. Fenn heals all living allies and clears poison.</li><li>Guard halves incoming damage until your next turn and restores 3 focus. Restore heals 25% of your own maximum HP.</li><li>A draught heals or revives the most wounded ally. Enemy special attacks arrive every third round. The enemy card warns you one round ahead, so you can guard or shield in time.</li><li>Winning restores all HP and revives the company. Focus needs a tonic, Guard, or a town rest.</li></ul><h3>Controls & saving</h3><p>Walk with arrow keys, WASD or the on-screen direction buttons. Click a landmark to walk toward it. Escape stops walking. Tab and Enter operate every control. Keys 1–4 open panels outside battle. Your adventure autosaves after each action. Use Camp to download or import a JSON backup. Sound is optional.</p><p>This first chronicle is a compact prototype with a complete ending. Its playtime has not been measured with human playtests.</p>`);}
function shop(selected){if(state.battle||!E.atLandmark(state)||E.nodeById(state.location).type!=='town')return;const hero=state.party.find(h=>h.id===selected)||state.party[0];const up=k=>{const lv=E.upgradeLevel(state,hero.id,k),u=E.UPGRADES[k],maxed=lv>=E.MAX_UPGRADE,price=E.upgradePrice(state,hero.id,k);return `<div class="item"><strong>${u.name} ${'◆'.repeat(lv)}${'◇'.repeat(E.MAX_UPGRADE-lv)} · ${maxed?'fully upgraded':price+' crowns'}</strong><small>${u.gain} per tier · tier ${lv} of ${E.MAX_UPGRADE}</small><button data-buy="${k}" ${maxed||state.gold<price?'disabled':''}>${maxed?'Maxed':'Buy for '+esc(hero.name)}</button></div>`;};
 dialog(`<div class="eyebrow">THE LANTERN OUTFITTER</div><h2>Useful things for dark roads.</h2><p>You have ${state.gold} crowns. Each hero can take two tiers of every upgrade. The second tier costs more.</p><label for="shop-hero">Equip hero </label><select id="shop-hero">${state.party.map(h=>`<option value="${h.id}" ${h.id===hero.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select><div class="item"><strong>Healing draught · ${E.SUPPLIES.potion} crowns</strong><small>You carry ${state.potions}</small><button data-buy="potion" ${state.gold<E.SUPPLIES.potion?'disabled':''}>Buy draught</button></div><div class="item"><strong>Focus tonic · ${E.SUPPLIES.tonic} crowns</strong><small>You carry ${state.tonics}</small><button data-buy="tonic" ${state.gold<E.SUPPLIES.tonic?'disabled':''}>Buy tonic</button></div>${['atk','hp','spd'].map(up).join('')}`);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.walk){stopWalking();step(...el.dataset.walk.split(',').map(Number));}else if(el.dataset.node){navigate(el.dataset.node);}
 else if(el.dataset.tab){if(state.battle)return;stopWalking();tab=el.dataset.tab;render();}
 else if(el.dataset.target){target=el.dataset.target;render();}
 else if(el.dataset.action){const action=el.dataset.action;if(E.act(state,action,action==='potion'?weakest().id:target)){chime('hit');save();render();}}
 else if(el.dataset.storyChoice){if(E.chooseStory(state,el.dataset.storyChoice)){chime();save();tab='world';render();focusStory();}}
 else if(el.dataset.choice){if(E.resolveEvent(state,el.dataset.choice)){chime();save();render();}}
 else if(el.dataset.ending){if(!state.flags.sun||state.ending)return;state.ending=el.dataset.ending;E.log(state,'The chronicle ended: '+(state.ending==='keeper'?'The Keeper of Morning.':'A Thousand Small Dawns.'));chime('win');save();render();}
 else if(el.dataset.buy){const selected=$('shop-hero').value;if(E.buy(state,el.dataset.buy,selected)){save();render();shop(selected);toast('Packed for the road.');}else toast('You need more crowns, or this upgrade is maxed.');}
 else if(el.dataset.do)perform(el.dataset.do);
});
function perform(action){stopWalking();switch(action){case'sail':if(E.sail(state)){save();render();}else toast('You need 40 crowns for passage.');break;case'begin':state.started=true;E.log(state,'Elin entrusted Vera with the last lantern.');save();render();break;case'finish':{const result=E.finishBattle(state);if(result){tab='world';chime(result==='victory'?'win':'click');save();render();focusStory();}break;}case'rest':if(!state.battle&&E.atLandmark(state)&&E.nodeById(state.location).type==='town'){E.healAll(state);save();render();toast('The fire is warm. Health and focus restored.');}break;case'shop':shop();break;case'train':{const n=E.nodeById(state.location);if(!state.battle&&n.optional&&state.cleared.includes(n.id)){E.startBattle(state,n);save();render();}break;}case'potion':if(state.potions&&!state.battle){const h=weakest();if(h.hp===h.maxHp){toast('Everyone is already at full health.');break;}state.potions--;const before=h.hp;h.hp=Math.min(h.maxHp,h.hp+E.POTION_HEAL);save();render();toast(h.name+' recovers '+(h.hp-before)+' HP.');}break;case'tonic':if(state.tonics&&!state.battle){if(state.party.every(h=>h.focus===h.maxFocus)){toast('Everyone already has full focus.');break;}state.tonics--;state.party.forEach(h=>h.focus=Math.min(h.maxFocus,h.focus+6));save();render();toast('The company recovers 6 focus each.');}break;case'export':download(JSON.stringify(state,null,2),'emberwake-save.json');toast('Your browser should now offer emberwake-save.json.');break;case'export-recovery':{const raw=saves.recovery();if(raw){download(raw,'emberwake-unreadable-save.json');toast('Your browser should now offer the old save file.');}break;}case'import':dialog('<h2>Replace this adventure?</h2><p>Choose an Emberwake save backup. Importing it replaces the current local adventure. Download a backup first if you want to keep it.</p><button class="primary" data-do="choose-file">Choose save file</button>');break;case'choose-file':$('import-file').click();break;case'reset':dialog('<h2>Start a new chronicle?</h2><p>Your current adventure will be replaced. Download a save backup from Camp if you want to return to it later.</p><button class="danger" data-do="confirm-reset">Replace adventure & begin again</button>');break;case'confirm-reset':clearTimeout(timer);timer=null;state=E.newGame();tab='world';$('modal').close();save();render();break;}}
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('large');const data=JSON.parse(await file.text());const migrated=E.migrateSave(data);if(!migrated)throw Error('invalid');clearTimeout(timer);timer=null;state=migrated;tab='world';$('modal').close();save();render();toast('Adventure restored from backup.');}catch{toast('This file is not a valid Emberwake save. Your adventure is unchanged.');}e.target.value='';});
$('close-modal').onclick=()=>$('modal').close();$('help').onclick=help;$('manage').onclick=()=>{if(state.battle){toast('Finish this battle before managing equipment.');return;}tab='pack';render();$('panel').scrollIntoView({behavior:'smooth',block:'nearest'});};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Disable sound':'Enable sound');chime();};document.querySelector('.brand').onclick=e=>{e.preventDefault();if(!state.battle){tab='world';render();}};document.addEventListener('keydown',e=>{if(state.battle||$('modal').open||e.target.matches('input,select,textarea'))return;if(e.key==='Escape'){stopWalking();return;}const directions={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]},dir=directions[e.key];if(dir&&state.started){e.preventDefault();stopWalking();step(...dir);return;}const i=Number(e.key)-1;if(i>=0&&i<=3){tab=['world','journal','pack','camp'][i];render();}});
render();if(loadProblem==='storage'){$('save-state').textContent='Save unavailable · use Camp backup';toast('This browser is blocking storage. Progress will not autosave; use Camp backups.');}else if(loadProblem==='invalid'){$('save-state').textContent=saves.recoveryDurable?'Old save kept · see Camp':'Autosave paused · see Camp';toast(saves.recoveryDurable?'Your previous save could not be read. A recovery copy is available in Camp.':'Your previous save could not be read. Autosave is paused to protect it. Open Camp for backups.');}

window.addEventListener('emberwake-art-ready',render);

function focusStory(){const heading=$('story-title');if(heading){heading.focus({preventScroll:true});heading.scrollIntoView({block:'nearest'});}}
$('modal').addEventListener('close',()=>render());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();else{stopWalking();clearTimeout(timer);timer=null;}});
document.addEventListener('change',e=>{if(e.target.id==='shop-hero')shop(e.target.value);});

function renderPartyStrip(){const strip=$('party-strip');strip.hidden=!state.battle;strip.innerHTML=state.party.map(h=>'<div class="'+(state.battle?.actor===h.id?'active-hero':'')+'"><b>'+esc(h.name)+'</b><small>'+h.hp+'/'+h.maxHp+' HP · '+h.focus+' focus</small><div class="track"><i style="width:'+pct(h.hp,h.maxHp)+'%"></i></div></div>').join('');}
